class Equipment:
    def __init__(self, weapon, armor):
        self.weapon = weapon
        self.armor = armor
    def summary(self):
        return {"weapon": self.weapon, "armor": self.armor}

class Character:
    def __init__(self, name, health, equipment):
        self.name = name
        self.health = health
        self.equipment = equipment
    def summary(self):
        return {"name": self.name, "health": self.health, "equipment": self.equipment.summary()}

class Party:
    def __init__(self, members):
        self.members = list(members)
    def total_health(self):
        total = 0
        for member in self.members:
            total = total + member.health
        return total
    def names(self):
        result = []
        for member in self.members:
            result.append(member.name)
        return result
    def summary(self):
        equipment = []
        for member in self.members:
            equipment.append(member.equipment.summary())
        return {
            "member_count": len(self.members),
            "total_health": self.total_health(),
            "names": self.names(),
            "equipment": equipment,
        }

def build_expedition():
    aria = Character("Aria", 10, Equipment("spear", "leather"))
    rook = Character("Rook", 14, Equipment("axe", "mail"))
    return Party([aria, rook])
